package com.cowave.search.common.security

import org.springframework.security.core.context.SecurityContextHolder
import org.springframework.security.oauth2.jwt.Jwt
import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken
import org.springframework.stereotype.Component

/**
 * SSO OIDC JWT 토큰에서 사용자 정보를 추출하는 유틸리티.
 *
 * Spring OAuth2 Resource Server가 검증한 JWT 클레임을 읽어 사용자 정보를 제공.
 * 클레임 키는 OIDC 표준(`email`, `preferred_username`) 기준이며,
 * SSO 제공자에 따라 `sub`, `name` 등으로 변경 가능.
 */
@Component
class SsoUserExtractor {
    companion object {
        const val CLAIM_EMAIL = "email"
        const val CLAIM_USERNAME = "preferred_username"
        const val CLAIM_ROLE = "dsearch_role"
    }

    /**
     * 현재 SecurityContext에서 인증된 사용자의 이메일을 반환.
     * 인증되지 않은 경우 null 반환.
     */
    fun currentEmail(): String? = currentJwt()?.getClaimAsString(CLAIM_EMAIL)

    /**
     * 현재 SecurityContext에서 인증된 사용자의 이름을 반환.
     */
    fun currentUsername(): String? = currentJwt()?.getClaimAsString(CLAIM_USERNAME)

    /**
     * 현재 SecurityContext에서 인증된 사용자의 SSO 역할 클레임을 반환.
     */
    fun currentRoleClaim(): String? = currentJwt()?.getClaimAsString(CLAIM_ROLE)

    private fun currentJwt(): Jwt? {
        val authentication = SecurityContextHolder.getContext().authentication
        return if (authentication is JwtAuthenticationToken) {
            authentication.token
        } else {
            null
        }
    }

    data class SsoUserInfo(
        val email: String,
        val username: String,
        val roleClaim: String?,
    )

    /**
     * 현재 사용자의 SSO 정보를 일괄 반환.
     * 인증되지 않은 경우 null 반환.
     */
    fun currentUserInfo(): SsoUserInfo? {
        val jwt = currentJwt() ?: return null
        val email = jwt.getClaimAsString(CLAIM_EMAIL) ?: return null
        val username = jwt.getClaimAsString(CLAIM_USERNAME) ?: email
        return SsoUserInfo(
            email = email,
            username = username,
            roleClaim = jwt.getClaimAsString(CLAIM_ROLE),
        )
    }
}

package com.cowave.search.config

import com.cowave.search.common.security.SsoProperties
import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Configuration
import org.springframework.http.HttpStatus
import org.springframework.security.config.annotation.web.builders.HttpSecurity
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity
import org.springframework.security.config.http.SessionCreationPolicy
import org.springframework.security.web.SecurityFilterChain

@Configuration
@EnableWebSecurity
class SecurityConfig(
    private val ssoProperties: SsoProperties,
) {
    @Bean
    fun securityFilterChain(http: HttpSecurity): SecurityFilterChain {
        val bypassUris = ssoProperties.bypassUri.toTypedArray()

        http
            .csrf { it.disable() }
            .sessionManagement { it.sessionCreationPolicy(SessionCreationPolicy.STATELESS) }
            .authorizeHttpRequests { auth ->
                auth.requestMatchers(*bypassUris).permitAll()
                auth.anyRequest().authenticated()
            }
            // SSO OIDC: JWT 토큰을 issuer-uri의 JWKS로 자동 검증
            .oauth2ResourceServer { oauth2 ->
                oauth2.jwt { }
            }
            // 인증 실패 처리: 401 반환
            .exceptionHandling { ex ->
                ex.authenticationEntryPoint { _, response, _ ->
                    response.status = HttpStatus.UNAUTHORIZED.value()
                    response.contentType = "application/json;charset=UTF-8"
                    response.writer.write("""{"message":"Unauthorized"}""")
                }
            }

        return http.build()
    }
}

