package com.cowave.search.common.elasticsearch

import co.elastic.clients.elasticsearch.ElasticsearchClient
import co.elastic.clients.json.jackson.JacksonJsonpMapper
import co.elastic.clients.transport.rest5_client.Rest5ClientTransport
import co.elastic.clients.transport.rest5_client.low_level.Rest5Client
import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.databind.SerializationFeature
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule
import com.fasterxml.jackson.module.kotlin.kotlinModule
import jakarta.annotation.PreDestroy
import org.apache.hc.core5.http.Header
import org.apache.hc.core5.http.HttpHost
import org.apache.hc.core5.http.message.BasicHeader
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Component
import java.util.Base64
import java.util.concurrent.ConcurrentHashMap

/**
 * 멀티 클러스터 Elasticsearch 클라이언트 팩토리.
 *
 * - ConcurrentHashMap 기반 클라이언트 캐시
 * - 클러스터 등록/삭제 시 캐시 갱신
 * - Basic 인증 및 ApiKey 인증 지원
 */
@Component
class ElasticsearchClientFactory {
    private val logger = LoggerFactory.getLogger(ElasticsearchClientFactory::class.java)

    private val clientCache = ConcurrentHashMap<String, CachedClusterClient>()

    private val jsonpMapper by lazy {
        val objectMapper =
            ObjectMapper()
                .registerModule(kotlinModule())
                .registerModule(JavaTimeModule())
                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
        JacksonJsonpMapper(objectMapper)
    }

    fun getClient(clusterId: String): ElasticsearchClient =
        clientCache[clusterId]?.esClient
            ?: throw IllegalArgumentException("등록되지 않은 클러스터입니다: $clusterId")

    fun getLowLevelClient(clusterId: String): Rest5Client =
        clientCache[clusterId]?.restClient
            ?: throw IllegalArgumentException("등록되지 않은 클러스터입니다: $clusterId")

    fun registerCluster(info: ClusterConnectionInfo) {
        val cached = buildCachedClient(info)
        clientCache[info.id] = cached
        logger.info("ES 클러스터 등록: {} ({}://{}:{})", info.id, info.scheme, info.host, info.port)
    }

    fun evictCluster(clusterId: String) {
        clientCache.remove(clusterId)?.let {
            runCatching { it.restClient.close() }
                .onFailure { e -> logger.warn("클러스터 클라이언트 종료 실패: $clusterId", e) }
        }
        logger.info("ES 클러스터 제거: {}", clusterId)
    }

    fun registeredClusterIds(): Set<String> = clientCache.keys.toSet()

    @PreDestroy
    fun closeAll() {
        clientCache.values.forEach { runCatching { it.restClient.close() } }
        clientCache.clear()
        logger.info("모든 ES 클러스터 클라이언트 종료 완료")
    }

    private fun buildCachedClient(info: ClusterConnectionInfo): CachedClusterClient {
        val host = HttpHost.create("${info.scheme}://${info.host}:${info.port}")
        val defaultHeaders = buildAuthHeaders(info)

        val restClient =
            Rest5Client
                .builder(host)
                .setDefaultHeaders(defaultHeaders)
                .build()

        val transport = Rest5ClientTransport(restClient, jsonpMapper)
        val esClient = ElasticsearchClient(transport)

        return CachedClusterClient(restClient, esClient)
    }

    private fun buildAuthHeaders(info: ClusterConnectionInfo): Array<Header> =
        when {
            !info.apiKey.isNullOrBlank() -> {
                arrayOf(BasicHeader("Authorization", "ApiKey ${info.apiKey}"))
            }
            !info.username.isNullOrBlank() && !info.password.isNullOrBlank() -> {
                val credentials = Base64.getEncoder().encodeToString("${info.username}:${info.password}".toByteArray())
                arrayOf(BasicHeader("Authorization", "Basic $credentials"))
            }
            else -> emptyArray()
        }

    private data class CachedClusterClient(
        val restClient: Rest5Client,
        val esClient: ElasticsearchClient,
    )

    data class ClusterConnectionInfo(
        val id: String,
        val scheme: String,
        val host: String,
        val port: Int,
        val username: String? = null,
        val password: String? = null,
        val apiKey: String? = null,
    )
}

package com.cowave.search.common.elasticsearch

import co.elastic.clients.elasticsearch.ElasticsearchClient
import co.elastic.clients.elasticsearch.indices.CreateIndexRequest
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Component

/**
 * DSearch 시스템 인덱스 초기화.
 *
 * 클러스터 등록 시 필요한 dsearch-* 인덱스가 없으면 자동 생성.
 * ES 9.x에서는 점(.) 접두사 인덱스가 제한되므로 dsearch- 접두사 사용.
 */
@Component
class SystemIndexInitializer(
    private val factory: ElasticsearchClientFactory,
) {
    private val logger = LoggerFactory.getLogger(SystemIndexInitializer::class.java)

    companion object {
        val SYSTEM_INDICES =
            listOf(
                "dsearch-index-history",
                "dsearch-index-status",
            )
    }

    fun initialize(clusterId: String) {
        val client =
            runCatching { factory.getClient(clusterId) }.getOrElse {
                logger.warn("클러스터 {} 클라이언트를 가져올 수 없습니다. 시스템 인덱스 초기화 스킵.", clusterId)
                return
            }

        SYSTEM_INDICES.forEach { indexName ->
            ensureIndexExists(client, clusterId, indexName)
        }
    }

    private fun ensureIndexExists(
        client: ElasticsearchClient,
        clusterId: String,
        indexName: String,
    ) {
        runCatching {
            val exists = client.indices().exists { it.index(indexName) }.value()
            if (!exists) {
                client.indices().create(
                    CreateIndexRequest
                        .Builder()
                        .index(indexName)
                        .build(),
                )
                logger.info("클러스터 {} 시스템 인덱스 생성: {}", clusterId, indexName)
            }
        }.onFailure { e ->
            logger.warn("클러스터 {} 시스템 인덱스 {} 초기화 실패: {}", clusterId, indexName, e.message)
        }
    }
}

package com.cowave.search.cluster.service

import co.elastic.clients.json.JsonData
import com.cowave.search.cluster.dto.ClusterRequest
import com.cowave.search.cluster.dto.ClusterResponse
import com.cowave.search.cluster.dto.ClusterStatusResponse
import com.cowave.search.cluster.infrastructure.ClusterRepository
import com.cowave.search.cluster.model.Cluster
import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory.ClusterConnectionInfo
import com.cowave.search.common.elasticsearch.SystemIndexInitializer
import com.cowave.search.common.exception.NotFoundException
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service
import java.time.LocalDateTime

@Service
class ClusterService(
    private val clusterRepository: ClusterRepository,
    private val clientFactory: ElasticsearchClientFactory,
    private val systemIndexInitializer: SystemIndexInitializer,
) {
    private val logger = LoggerFactory.getLogger(ClusterService::class.java)

    fun findAll(includeStatus: Boolean): List<ClusterResponse> =
        clusterRepository.findAll().map { cluster ->
            val status = if (includeStatus) scanClusterStatus(cluster.id) else null
            ClusterResponse.from(cluster, status)
        }

    fun findById(id: String): ClusterResponse {
        val cluster =
            clusterRepository
                .findById(id)
                .orElseThrow { NotFoundException("존재하지 않는 클러스터입니다: $id") }
        val status = scanClusterStatus(id)
        return ClusterResponse.from(cluster, status)
    }

    fun create(request: ClusterRequest): ClusterResponse {
        val cluster =
            clusterRepository.save(
                Cluster(
                    name = request.name,
                    scheme = request.scheme,
                    host = request.host,
                    port = request.port,
                    kibana = request.kibana,
                    theme = request.theme,
                    username = request.username,
                    password = request.password,
                    dictionaryRemoteClusterId = request.dictionaryRemoteClusterId,
                    autocompleteUrl = request.autocompleteUrl,
                ),
            )

        clientFactory.registerCluster(
            ClusterConnectionInfo(
                id = cluster.id,
                scheme = cluster.scheme,
                host = cluster.host,
                port = cluster.port,
                username = cluster.username,
                password = cluster.password,
            ),
        )

        systemIndexInitializer.initialize(cluster.id)

        return ClusterResponse.from(cluster)
    }

    fun delete(
        id: String,
        removeData: Boolean,
    ): ClusterResponse {
        val cluster =
            clusterRepository
                .findById(id)
                .orElseThrow { NotFoundException("존재하지 않는 클러스터입니다: $id") }

        if (removeData) {
            deleteSystemIndices(id)
        }

        clientFactory.evictCluster(id)
        clusterRepository.delete(cluster)

        return ClusterResponse.from(cluster)
    }

    fun update(
        id: String,
        request: ClusterRequest,
    ): ClusterResponse {
        val cluster =
            clusterRepository
                .findById(id)
                .orElseThrow { NotFoundException("존재하지 않는 클러스터입니다: $id") }

        cluster.name = request.name
        cluster.scheme = request.scheme
        cluster.host = request.host
        cluster.port = request.port
        cluster.kibana = request.kibana
        cluster.theme = request.theme
        cluster.username = request.username
        cluster.password = request.password
        cluster.dictionaryRemoteClusterId = request.dictionaryRemoteClusterId
        cluster.autocompleteUrl = request.autocompleteUrl
        cluster.updateDate = LocalDateTime.now()

        clientFactory.evictCluster(id)
        clientFactory.registerCluster(
            ClusterConnectionInfo(
                id = cluster.id,
                scheme = cluster.scheme,
                host = cluster.host,
                port = cluster.port,
                username = cluster.username,
                password = cluster.password,
            ),
        )

        return ClusterResponse.from(clusterRepository.save(cluster))
    }

    private fun scanClusterStatus(clusterId: String): ClusterStatusResponse =
        runCatching {
            val client = clientFactory.getClient(clusterId)

            val nodesResponse = client.nodes().info { req -> req }
            val nodeCount = nodesResponse.nodes().size

            val statsResponse = client.cluster().stats { req -> req }
            val shardCount =
                statsResponse
                    .indices()
                    .shards()
                    .total()
                    ?.toInt() ?: 0
            val indexCount = statsResponse.indices().count().toInt()
            val storeSizeBytes = statsResponse.indices().store().sizeInBytes()
            val storeSize = formatBytes(storeSizeBytes)

            ClusterStatusResponse(
                connection = true,
                nodeCount = nodeCount,
                shardCount = shardCount,
                indexCount = indexCount,
                storeSize = storeSize,
            )
        }.getOrElse { e ->
            logger.warn("클러스터 {} 상태 조회 실패: {}", clusterId, e.message)
            ClusterStatusResponse(connection = false)
        }

    private fun deleteSystemIndices(clusterId: String) {
        runCatching {
            val client = clientFactory.getClient(clusterId)
            SystemIndexInitializer.SYSTEM_INDICES.forEach { indexName ->
                runCatching {
                    client.indices().delete { it.index(indexName) }
                    logger.info("클러스터 {} 시스템 인덱스 삭제: {}", clusterId, indexName)
                }.onFailure { e ->
                    logger.warn("클러스터 {} 시스템 인덱스 {} 삭제 실패: {}", clusterId, indexName, e.message)
                }
            }
        }.onFailure { e ->
            logger.warn("클러스터 {} 데이터 삭제 중 오류: {}", clusterId, e.message)
        }
    }

    fun toggleMaintenanceMode(
        clusterId: String,
        flag: Boolean,
    ) {
        val client = clientFactory.getClient(clusterId)
        val rerouteValue = if (flag) "none" else "all"
        runCatching {
            client.cluster().putSettings { settings ->
                settings.persistent(
                    mapOf("cluster.routing.allocation.enable" to JsonData.of(rerouteValue)),
                )
            }
            logger.info("클러스터 {} 점검 모드 {}: 샤드 재분배 → {}", clusterId, if (flag) "시작" else "해제", rerouteValue)
        }.onFailure { e ->
            logger.warn("클러스터 {} 점검 모드 설정 실패: {}", clusterId, e.message)
        }
    }

    private fun formatBytes(bytes: Long): String {
        val kb = bytes / 1024.0
        val mb = kb / 1024.0
        val gb = mb / 1024.0
        return when {
            gb >= 1 -> "%.1fgb".format(gb)
            mb >= 1 -> "%.1fmb".format(mb)
            kb >= 1 -> "%.1fkb".format(kb)
            else -> "${bytes}b"
        }
    }
}

package com.cowave.search.cluster.service

import com.cowave.search.cluster.infrastructure.ClusterRepository
import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory.ClusterConnectionInfo
import org.slf4j.LoggerFactory
import org.springframework.boot.ApplicationArguments
import org.springframework.boot.ApplicationRunner
import org.springframework.stereotype.Component

/**
 * 애플리케이션 시작 시 DB에 저장된 클러스터를 ES 클라이언트 팩토리에 등록.
 * 서버 재시작 시에도 클라이언트 캐시가 자동 복원된다.
 */
@Component
class ClusterInitializer(
    private val clusterRepository: ClusterRepository,
    private val clientFactory: ElasticsearchClientFactory,
) : ApplicationRunner {
    private val logger = LoggerFactory.getLogger(ClusterInitializer::class.java)

    override fun run(args: ApplicationArguments) {
        val clusters = clusterRepository.findAll()
        logger.info("저장된 클러스터 {}개를 ES 클라이언트 팩토리에 등록합니다.", clusters.size)

        clusters.forEach { cluster ->
            runCatching {
                clientFactory.registerCluster(
                    ClusterConnectionInfo(
                        id = cluster.id,
                        scheme = cluster.scheme,
                        host = cluster.host,
                        port = cluster.port,
                        username = cluster.username,
                        password = cluster.password,
                    ),
                )
            }.onFailure { e ->
                logger.warn("클러스터 {} ({}) 등록 실패: {}", cluster.id, cluster.name, e.message)
            }
        }

        logger.info("클러스터 초기화 완료: {}개 등록", clientFactory.registeredClusterIds().size)
    }
}

