{"result":"package com.cowave.search.cluster.service

import co.elastic.clients.json.JsonData
import com.cowave.search.cluster.dto.NodeMoveInfoResponse
import com.cowave.search.cluster.dto.ShardMoveInfo
import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service
import java.util.UUID

@Service
class NodeService(
    private val clientFactory: ElasticsearchClientFactory,
) {
    private val logger = LoggerFactory.getLogger(NodeService::class.java)

    fun getMovingShardNodes(clusterId: UUID): List<NodeMoveInfoResponse> {
        val client = clientFactory.getClient(clusterId)

        return runCatching {
            val recovery = client.indices().recovery { it.activeOnly(true) }
            val nodeShardMap = mutableMapOf<String, MutableList<ShardMoveInfo>>()

            // RecoveryResponse.statuses(): Map<String, RecoveryStatus>
            recovery.statuses().forEach { (indexName, recoveryStatus) ->
                // RecoveryStatus.shards(): List<ShardRecovery>
                recoveryStatus.shards().forEach { shard ->
                    if (shard.stage() != "done") {
                        val toNode = shard.target()?.name() ?: return@forEach
                        val fromNode = shard.source()?.name() ?: ""
                        val shardInfo =
                            ShardMoveInfo(
                                index = indexName,
                                shardId = shard.id(),
                                fromNode = fromNode,
                                toNode = toNode,
                            )
                        nodeShardMap.getOrPut(toNode) { mutableListOf() }.add(shardInfo)
                    }
                }
            }

            nodeShardMap.map { (node, shards) ->
                NodeMoveInfoResponse(node = node, shards = shards)
            }
        }.getOrElse { e ->
            logger.warn("클러스터 {} 샤드 이동 정보 조회 실패: {}", clusterId, e.message)
            emptyList()
        }
    }

    fun getExcludedNodes(clusterId: UUID): List<String> {
        val client = clientFactory.getClient(clusterId)

        return runCatching {
            val settings = client.cluster().getSettings { it.includeDefaults(false) }
            val excludedIpData = settings.persistent()["cluster.routing.allocation.exclude._ip"]
            val excludedIp = excludedIpData?.to(String::class.java) ?: ""
            if (excludedIp.isBlank()) emptyList() else excludedIp.split(",").filter { it.isNotBlank() }
        }.getOrElse { e ->
            logger.warn("클러스터 {} 제외된 노드 목록 조회 실패: {}", clusterId, e.message)
            emptyList()
        }
    }

    fun removeNode(
        clusterId: UUID,
        params: Map<String, String>,
    ): String {
        val client = clientFactory.getClient(clusterId)

        return runCatching {
            client.cluster().putSettings { req ->
                req.persistent(params.mapValues { (_, v) -> JsonData.of(v) })
            }
            "노드 제거 설정이 적용되었습니다."
        }.getOrElse { e ->
            logger.warn("클러스터 {} 노드 제거 실패: {}", clusterId, e.message)
            "노드 제거 설정 적용 실패: ${e.message}"
        }
    }
}"}

