package com.cowave.search.auth.service

import com.cowave.search.auth.dto.CreateRoleRequest
import com.cowave.search.auth.dto.RoleListResponse
import com.cowave.search.auth.dto.RoleResponse
import com.cowave.search.auth.dto.UserRoleResponse
import com.cowave.search.auth.infrastructure.RoleRepository
import com.cowave.search.auth.infrastructure.UserRoleRepository
import com.cowave.search.auth.model.Role
import com.cowave.search.common.exception.NotFoundException
import org.springframework.stereotype.Service
import java.time.LocalDateTime

@Service
class RoleService(
    private val roleRepository: RoleRepository,
    private val userRoleRepository: UserRoleRepository,
) {
    fun findAll(): RoleListResponse {
        val roles = roleRepository.findAll().map { RoleResponse.from(it) }
        val userRoles =
            userRoleRepository.findAll().map {
                UserRoleResponse(id = it.id, userId = it.userId, roleId = it.roleId)
            }
        return RoleListResponse(roles = roles, userRoles = userRoles)
    }

    fun findById(id: String): RoleResponse {
        val role =
            roleRepository
                .findById(id)
                .orElseThrow { NotFoundException("존재하지 않는 역할입니다: $id") }
        return RoleResponse.from(role)
    }

    fun create(request: CreateRoleRequest): RoleResponse {
        val role =
            roleRepository.save(
                Role(
                    name = request.name,
                    analysis = request.analysis,
                    index = request.index,
                    search = request.search,
                    manage = request.manage,
                ),
            )
        return RoleResponse.from(role)
    }

    fun update(
        id: String,
        request: CreateRoleRequest,
    ): RoleResponse {
        val role =
            roleRepository
                .findById(id)
                .orElseThrow { NotFoundException("존재하지 않는 역할입니다: $id") }

        role.name = request.name
        role.analysis = request.analysis
        role.index = request.index
        role.search = request.search
        role.manage = request.manage
        role.updateDate = LocalDateTime.now()

        return RoleResponse.from(roleRepository.save(role))
    }

    fun delete(id: String): RoleResponse {
        val role =
            roleRepository
                .findById(id)
                .orElseThrow { NotFoundException("존재하지 않는 역할입니다: $id") }
        roleRepository.delete(role)
        return RoleResponse.from(role)
    }
}

